def _git_bytes(repo, *args):
    return subprocess.run(["git", "-C", str(repo.root), *args], check=True,
                          capture_output=True).stdout


def _index_cli(repo, *args):
    environment = os.environ.copy()
    environment["PYTHONPATH"] = str(Path(__file__).resolve().parents[1] / "src")
    return subprocess.run([sys.executable, "-m", "gita", *args], cwd=repo.root,
                          env=environment, capture_output=True, text=True,
                          encoding="utf-8", check=False)


def _successful_payload(process):
    assert process.returncode == 0, f"CLI exited {process.returncode}: {process.stderr[:1200]}"
    payload = json.loads(process.stdout)
    assert isinstance(payload, dict)
    assert set(payload) >= {
        "schema_version", "command", "status", "scope", "generation", "revision",
        "boundary", "policy", "refs", "freshness", "coverage", "results", "page",
        "omitted", "error",
    }
    assert payload["error"] is None
    assert payload["scope"] is not None
    assert payload["generation"] is not None
    assert isinstance(payload["results"], list)
    return payload


def _assert_history_events(events, fixture, eid):
    """Require qualified OIDs and original-source occurrence locators in history JSON."""
    assert isinstance(events, list)
