@pytest.mark.parametrize("corruption", (
    "previous_source_commit", "move_endpoints", "move_paths", "material", "diagnostic_only_sha",
    "event_order", "literal_names", "byte_bounds", "root_parent", "missing_source", "missing_span",
))
def test_history_event_assertions_reject_corrupted_responses(refactor_repo, corruption):
    eid = "eid1_" + "11" * 32
    events = _expected_history_events(refactor_repo, eid)
    if corruption == "previous_source_commit":
        events[1]["source"]["commit"]["hex"] = refactor_repo["commits"][1]
    elif corruption == "move_endpoints":
        events[3]["source"], events[3]["destination"] = events[3]["destination"], events[3]["source"]
    elif corruption == "move_paths":
        source, destination = events[3]["source"], events[3]["destination"]
        source["path_bytes_b64"], destination["path_bytes_b64"] = destination["path_bytes_b64"], source["path_bytes_b64"]
    elif corruption == "material":
        events[1]["material"] = False
    elif corruption == "diagnostic_only_sha":
        events[1]["diagnostic"] = refactor_repo["commits"][1]
        del events[1]["commit"]
    elif corruption == "event_order":
        events[1], events[4] = events[4], events[1]
    elif corruption == "literal_names":
        events[2]["source"]["names"] = ["check_token"]
    elif corruption == "byte_bounds":
        events[1]["destination"]["span"]["end_byte"] -= 1
    elif corruption == "root_parent":
        events[0]["parent"] = dict(events[0]["commit"])
    elif corruption == "missing_source":
        events[1]["source"] = None
    elif corruption == "missing_span":
        del events[1]["destination"]["span"]
    with pytest.raises(AssertionError):
        _assert_history_events(events, refactor_repo, eid)


