def _f1_worker_stall(connection, *, reached, release, before_read=False):
    try:
        if not before_read:
            connection.recv()
        reached.set()
        release.acquire(timeout=15.0)
    finally:
        connection.close()


def _f1_worker_crash(connection, *, reached):
    connection.recv()
    reached.set()
    os._exit(23)


def _f1_worker_malformed(connection, *, reached, release, response):
    try:
        connection.recv()
        reached.set()
        connection.send(response)
        release.acquire(timeout=15.0)
    finally:
        connection.close()


@pytest.fixture
def f1_worker_processes(monkeypatch):
    import multiprocessing

    spawn_context = multiprocessing.get_context("spawn")
    process_constructor = spawn_context.Process
    processes = []

    def record_process(*args, **kwargs):
        process = process_constructor(*args, **kwargs)
        processes.append(process)
        return process

    monkeypatch.setattr(type(spawn_context), "Process", staticmethod(record_process))
    try:
        yield processes
    finally:
        for process in processes:
            try:
                if process.pid is not None:
                    if process.is_alive():
                        process.terminate()
                    process.join(5.0)
                    if process.is_alive():
                        process.kill()
                        process.join(5.0)
                    assert not process.is_alive(), "spawned test worker survived cleanup"
                process.close()
            except ValueError:
                pass


def _f1_assert_worker_reaped(processes):
    assert len(processes) == 1
    process = processes[0]
    assert process.pid is not None
    assert process.exitcode is not None
    assert not process.is_alive()


def _f1_assert_worker_terminal(worker, processes):
    from gita.index.worker import EvidenceWorkerError

    process_count = len(processes)
    with pytest.raises(EvidenceWorkerError) as closed:
        worker.parse(b"pass\n", b"auth.py")
    assert closed.value.code == "worker_closed"
    assert len(processes) == process_count
    worker.close()
    worker.close()


def test_parallel_build_overlaps_parses_and_preserves_serial_evidence(repo, tmp_path, monkeypatch):
    from threading import Barrier, Lock

    from gita.index import builder, evidence
    from gita.index.store import IndexStore
    from gita.vcs.git import CommittedRepo

    barrier = Barrier(2, timeout=10)
    lock = Lock()
    started = 0

    class Worker:
        def __init__(self, timeout):
            pass

        def __enter__(self):
            return self

        def __exit__(self, *args):
            pass

        def parse(self, source, path, object_format, limits):
            nonlocal started
            with lock:
                started += 1
                overlapping = started <= 2
            if overlapping:
                barrier.wait()
            return evidence.parse_evidence(source, path, object_format, limits)

    snapshots = []
    contexts = []
    for workers in (1, 2):
        with monkeypatch.context() as patch:
            if workers == 2:
                patch.setattr(builder, "EvidenceWorker", Worker)
            with CommittedRepo(repo.root) as repository, IndexStore.create(tmp_path / f"workers-{workers}.sqlite") as store:
                result = builder.build(repository, store, limits=builder.BuildLimits(workers=workers))
                contexts.append(result.context)
                snapshots.append({table: tuple(tuple(row) for row in store.connection.execute(
                    f"SELECT * FROM {table} ORDER BY id",
                )) for table in ("parse_result", "version", "definition", "lineage", "occurrence", "event", "lineage_link")})
    assert started >= 2
    assert contexts[0] == contexts[1]
    assert snapshots[0] == snapshots[1]


def test_worker_reuses_fingerprint_per_limits_without_changing_evidence(monkeypatch):
    from dataclasses import replace

    from gita.index import evidence, worker

    limits = evidence.EvidenceLimits()
    changed = replace(limits, max_definitions=1)
    source = b"def run():\n    return 1\n"
    requests = [("parse", source, b"app.py", "sha1", policy)
                for policy in (limits, limits, changed, limits)]
    expected = [evidence.parse_evidence(source, b"app.py", limits=request[-1])
                for request in requests]
    original = evidence.parse_fingerprint
    calls = []

    def fingerprint(policy):
        calls.append(policy)
        return original(policy)

    class Connection:
        def __init__(self):
            self.requests = iter(requests)
            self.responses = []
            self.closed = False

        def recv(self):
            try:
                return next(self.requests)
            except StopIteration:
                raise EOFError from None

        def send(self, response):
            self.responses.append(response)

        def close(self):
            self.closed = True

    monkeypatch.setattr(evidence, "parse_fingerprint", fingerprint)
    connection = Connection()
    worker._serve(connection)
    assert calls == [limits, changed]
    assert connection.responses == [("success", bundle) for bundle in expected]
    assert connection.closed


