    @pytest.mark.parametrize("reorder", (False, True), ids=("line-shift", "reorder"))
    def test_distinct_overload_siblings_keep_identity_without_ordinal_matching(
        self, _build_repo, _builder_store, reorder, monkeypatch,
    ):
        from gita.index import matching
        from gita.index.builder import BuildLimits

        def forbidden(*args):
            pytest.fail("exact sibling matching must not depend on fuzzy similarity")

        monkeypatch.setattr(matching, "similarity", forbidden)
        declarations = [
            f"    @t.overload\n    def __init__(self, value: {annotation}) -> None: ...\n".encode()
            for annotation in ("str", "bytes", "bytearray", "memoryview", "int")
        ]
        declarations.append(b"    def __init__(self, value):\n        self.value = str(value).strip()\n")
        header = b"import typing as t\n\nclass Serializer:\n"
        before_source = header + b"\n".join(declarations)
        after_source = b"\n\n" + header + b"\n".join(
            list(reversed(declarations[:-1])) + declarations[-1:] if reorder else declarations
        )
        fixture = _build_repo({b"auth.py": before_source}, {b"auth.py": after_source})
        result = self._build(fixture, _builder_store, limits=BuildLimits(max_pairs=0))
        before, after = [self._bindings(
            _builder_store, result, sequence, names=("Serializer", "__init__"),
        ) for sequence in (0, 1)]
        assert len(before) == len(after) == 6
        old_by_source = {item["version"].source_digest: item for item in before}
        assert len(old_by_source) == 6
        for item in after:
            old = old_by_source[item["version"].source_digest]
            assert item["eid"] == old["eid"]
            assert item["occurrence"].id != old["occurrence"].id
            assert all(event.commit == fixture["commits"][0]
                       for event in self._events(_builder_store, result, item["eid"]))
        links = [link for link in self._links(_builder_store, result)
                 if link.source in {item["occurrence"].id for item in before}
                 and link.status.value == "accepted"]
        assert len(links) == 6
        assert {link.method for link in links} == {"exact_own"}
        for link in links:
            evidence = dict(link.evidence)
            assert evidence["matching_scope"] == "same-locator-established-parent-siblings"
            assert evidence["source_count"] == evidence["destination_count"] == 1
            assert evidence["sibling_source_count"] == evidence["sibling_destination_count"] == 6
        assert _builder_store.check_integrity() == ()

    @pytest.mark.parametrize("case", ("edit", "duplicate", "insert", "retained-copy", "body-copy", "parse-gap"))
    def test_exact_sibling_matches_keep_full_population_and_unmatched_guards(
        self, _build_repo, _builder_store, case,
    ):
        first = self._TOKEN
        second = self._OTHER.replace(b"count_items", b"validate_token")
        original = {b"auth.py": first + b"\n" + second}
        changed = {b"auth.py": b"\n\n" + first + b"\n" + second}
        expected = {first[:-1], second[:-1]}
        if case == "edit":
            changed[b"auth.py"] = changed[b"auth.py"].replace(b"total * 7", b"total * 11")
            expected.remove(second[:-1])
        elif case == "duplicate":
            changed[b"auth.py"] += b"\n" + second
            expected.remove(second[:-1])
        elif case == "insert":
            changed[b"auth.py"] += b"\ndef validate_token(value):\n    return value.upper().strip()\n"
        elif case == "retained-copy":
            original[b"copy.py"] = changed[b"copy.py"] = first
            expected.remove(first[:-1])
        elif case == "body-copy":
            changed[b"copy.py"] = first.replace(b"validate_token", b"copied")
            expected.remove(first[:-1])
        else:
            changed[b"broken.py"] = b"def invalid(:\n"
            expected.clear()
        fixture = _build_repo(original, changed)
        result = self._build(fixture, _builder_store)
        before, after = [self._bindings(
            _builder_store, result, sequence, path=b"auth.py", names=("validate_token",),
        ) for sequence in (0, 1)]
        preserved = set()
        for item in before:
            span = item["definition"].span
            source = original[b"auth.py"][span.start_byte:span.end_byte]
            continuations = [new for new in after if new["eid"] == item["eid"]]
            assert len(continuations) == int(source in expected)
            if continuations:
                preserved.add(source)
                assert item["version"].own == continuations[0]["version"].own
            else:
                assert self._departure(_builder_store, result, item["eid"])["status"] == "unknown"
        assert preserved == expected
        old_ids = {item["eid"] for item in before}
        for item in after:
            if item["eid"] not in old_ids:
                assert item["eid"].startswith(("eid1_", "oeid1_"))
                assert not any(link.status.value == "accepted" and link.destination == item["occurrence"].id
                               for link in self._links(_builder_store, result))
        assert _builder_store.check_integrity() == ()

    @pytest.mark.parametrize("changed_child", (False, True), ids=("reorder", "child-edit"))
    def test_duplicate_container_siblings_require_complete_subtrees(
        self, _build_repo, _builder_store, changed_child,
    ):
        first = b"class Handler:\n    def run(self, value):\n        return value.strip().lower()\n"
        second = b"class Handler:\n    def run(self, value):\n        return value.upper().split()\n"
        replacement = first.replace(b"lower()", b"title()") if changed_child else first
        fixture = _build_repo({b"auth.py": first + b"\n" + second},
                              {b"auth.py": second + b"\n" + replacement})
        result = self._build(fixture, _builder_store)
        before, after = [self._bindings(_builder_store, result, sequence, names=("Handler",))
                         for sequence in (0, 1)]
        assert before[0]["version"].own == before[1]["version"].own
        old_ids = {item["eid"] for item in before}
        assert len(old_ids.intersection(item["eid"] for item in after)) == (1 if changed_child else 2)
        for item in after:
            if item["eid"] in old_ids:
                old = next(old for old in before if old["eid"] == item["eid"])
                assert old["version"].subtree == item["version"].subtree
                links = [link for link in self._links(_builder_store, result)
                         if link.source == old["occurrence"].id and link.destination == item["occurrence"].id]
                assert len(links) == 1 and links[0].method == "exact_subtree"

    @pytest.mark.parametrize("distinctive", (False, True), ids=("identical-prepend", "distinctive-reorder"))
    def test_duplicate_siblings_never_continue_by_ordinal(self, _build_repo, _builder_store, distinctive):
        duplicate = self._TOKEN
        if distinctive:
            second = self._OTHER.replace(b"count_items", b"validate_token")
            before_source, after_source = duplicate + b"\n" + second, second + b"\n" + duplicate
        else:
            before_source, after_source = duplicate * 2, duplicate * 3
        fixture = _build_repo({b"auth.py": before_source}, {b"auth.py": after_source})
        result = self._build(fixture, _builder_store)
        before = self._bindings(_builder_store, result, 0, synthetic=False)
        after = self._bindings(_builder_store, result, 1, synthetic=False)
        assert len(before) == 2 and len(after) == (2 if distinctive else 3)
        old_ids = {item["eid"] for item in before}
        leaf_links = [link for link in self._links(_builder_store, result)
                      if link.source in {item["occurrence"].id for item in before}]
        assert not any(link.status.value == "accepted" and link.method == "structural_locator"
                       for link in leaf_links)
        if distinctive:
            accepted = [link for link in leaf_links if link.status.value == "accepted"]
            assert leaf_links
            for link in accepted:
                old = next(item for item in before if item["occurrence"].id == link.source)
                new = next(item for item in after if item["occurrence"].id == link.destination)
                assert old["version"].own == new["version"].own
                assert old["eid"] == new["eid"]
            for item in after:
                if item["eid"] in old_ids:
                    old = next(old for old in before if old["eid"] == item["eid"])
                    assert old["version"].own == item["version"].own
                else:
                    assert item["eid"].startswith("oeid1_")
        else:
            assert old_ids.isdisjoint(item["eid"] for item in after)
            assert all(item["eid"].startswith("oeid1_") for item in after)
            assert any(link.status.value == "ambiguous" for link in leaf_links)
            assert all(self._departure(_builder_store, result, eid)["status"] == "unknown" for eid in old_ids)

    @pytest.mark.parametrize("case", ("retained-copy", "two-destinations", "swap"))
    def test_copy_and_swap_populations_do_not_conflate_identities(self, _build_repo, _builder_store, case):
        if case == "swap":
            second = self._OTHER.replace(b"count_items", b"second")
            before_files = {b"auth.py": self._TOKEN + b"\n" + second}
            after_files = {b"auth.py": (
                second.replace(b"second", b"validate_token") + b"\n"
                + self._TOKEN.replace(b"validate_token", b"second")
            )}
        else:
            before_files = {b"auth.py": self._TOKEN}
            after_files = {b"copy.py": self._TOKEN}
            after_files[b"auth.py" if case == "retained-copy" else b"other.py"] = self._TOKEN
        fixture = _build_repo(before_files, after_files)
        result = self._build(fixture, _builder_store)
        before = self._bindings(_builder_store, result, 0, synthetic=False)
        after = self._bindings(_builder_store, result, 1, synthetic=False)
        assert len(after) == 2
        if case == "retained-copy":
            retained = self._one(_builder_store, result, 1, path=b"auth.py", synthetic=False)
            copied = self._one(_builder_store, result, 1, path=b"copy.py", synthetic=False)
            assert retained["eid"] == before[0]["eid"] != copied["eid"]
            assert not any(link.status.value == "accepted" and link.destination == copied["occurrence"].id
                           for link in self._links(_builder_store, result))
        else:
            assert {item["eid"] for item in before}.isdisjoint(item["eid"] for item in after)
            assert all(item["eid"].startswith("oeid1_") for item in after)
            sources = {item["occurrence"].id for item in before}
            links = [link for link in self._links(_builder_store, result) if link.source in sources]
            assert links and any(link.status.value == "ambiguous" for link in links)
            assert not any(link.status.value == "accepted" for link in links)
            assert all(self._departure(_builder_store, result, item["eid"])["status"] == "unknown"
                       for item in before)

