    def test_small_pages_keep_unchanged_file_state_sparse(self, _build_repo, _builder_store):
        from gita.index.builder import BuildLimits

        versions = ({b"auth.py": self._TOKEN},) + tuple(
            {b"auth.py": self._TOKEN, b"notes.txt": f"unrelated edit {number}\n".encode("ascii")}
            for number in range(10)
        )
        fixture = _build_repo(*versions)
        result = self._build(fixture, _builder_store, limits=BuildLimits(page_size=2))
        assert _builder_store.members(result.generation) == fixture["commits"]
        intervals = _builder_store.connection.execute(
            "SELECT from_seq, to_seq, binding_set_id FROM file_state WHERE generation_id = ? AND path = ?",
            (result.generation, b"auth.py"),
        ).fetchall()
        assert len(intervals) == 1 and tuple(intervals[0])[:2] == (0, None)
        assert _builder_store.connection.execute(
            "SELECT count(*) FROM binding JOIN definition ON definition.id = binding.definition_id "
            "WHERE binding_set_id = ? AND synthetic_root = 0", (intervals[0]["binding_set_id"],),
        ).fetchone()[0] == 1
        states = [self._one(_builder_store, result, sequence, synthetic=False) for sequence in range(11)]
        assert len({item["eid"] for item in states}) == 1
        assert len({item["occurrence"].id for item in states}) == 11
        assert len(self._events(_builder_store, result, states[0]["eid"])) == 1
        assert _builder_store.connection.execute(
            "SELECT count(*) FROM occurrence WHERE id NOT IN ("
            "SELECT occurrence_id FROM lineage UNION SELECT source FROM lineage_link "
            "UNION SELECT destination FROM lineage_link UNION SELECT source FROM event WHERE source IS NOT NULL "
            "UNION SELECT destination FROM event WHERE destination IS NOT NULL UNION SELECT occurrence_id FROM departure)",
        ).fetchone()[0] == 0
        assert _builder_store.connection.execute("SELECT count(*) FROM occurrence").fetchone()[0] == 2

    def test_builder_never_delegates_identity_to_legacy_diff(self, _build_repo, _builder_store, monkeypatch):
        import socket

        from gita.diff import differ

        def forbidden(*args, **kwargs):
            pytest.fail("committed lineage must not use legacy matching or network services")

        monkeypatch.setattr(differ, "diff_trees", forbidden)
        monkeypatch.setattr(differ, "reconcile_moves", forbidden)
        monkeypatch.setattr(socket, "create_connection", forbidden)
        fixture = _build_repo({b"auth.py": self._TOKEN}, {
            b"auth.py": b"# moved\n", b"security.py": self._TOKEN.replace(b"validate_token", b"check_token"),
        })
        result = self._build(fixture, _builder_store)
