    @pytest.mark.parametrize("boundary", ("bounded", "shallow", "missing_parent"))
    def test_explicit_since_at_published_anchor_requires_bounded_context(
        self, _build_repo, _builder_store, monkeypatch, boundary,
    ):
        import stat

        from gita.index import builder
        from gita.vcs.git import CommittedRepo

        fixture = _build_repo({b"auth.py": self._TOKEN}, {
            b"auth.py": self._TOKEN.replace(b"== 3", b">= 3"),
        })
        parent, anchor = fixture["commits"]
        request = {}
        if boundary == "bounded":
            request["since"] = anchor.digest.hex()
        elif boundary == "shallow":
            (fixture["root"] / ".git" / "shallow").write_bytes(
                anchor.digest.hex().encode("ascii") + b"\n",
            )
        else:
            missing = parent.digest.hex()
            loose_parent = fixture["root"] / ".git" / "objects" / missing[:2] / missing[2:]
            loose_parent.chmod(stat.S_IWRITE | stat.S_IREAD)
            loose_parent.unlink()
        original = self._build(fixture, _builder_store, **request)
        assert original.tip == original.context.anchor == anchor
        assert original.context.boundary == boundary and original.context.parents == (parent,)
        assert original.commits == 1 and _builder_store.members(original.generation) == (anchor,)
        observed = self._one(_builder_store, original, 0, synthetic=False)
        assert observed["eid"].startswith("oeid1_")
        assert self._events(_builder_store, original, observed["eid"])[0].flags == ("observed",)
        before = self._database_rows(_builder_store)

        def forbidden(*args, **kwargs):
            pytest.fail("an explicit boundary decision at the published tip must not replay or copy history")

        with monkeypatch.context() as guard:
            for name in ("commit", "object_info", "iter_tree", "read_object", "changes", "shallow_boundaries"):
                guard.setattr(CommittedRepo, name, forbidden)
            guard.setattr(builder.EvidenceWorker, "__init__", forbidden)
            guard.setattr(builder._Builder, "advance", forbidden)
            if boundary == "bounded":
                repeated = self._build(fixture, _builder_store, since=anchor.digest.hex())
                assert repeated.generation == original.generation
                assert repeated.context == original.context and repeated.tip == original.tip
                assert (repeated.commits, repeated.parsed_files, repeated.cached_files) == (1, 0, 0)
            else:
                with pytest.raises(builder.BuildError) as refused:
                    self._build(fixture, _builder_store, since=anchor.digest.hex())
                assert refused.value.code == "rebuild_required"
        assert _builder_store.published_generation("default") == original.generation
        assert self._database_rows(_builder_store) == before

    @pytest.mark.parametrize("changed", ("boundary", "parse_fingerprint", "match_fingerprint"))
    def test_incompatible_local_context_refuses_before_any_history_walk(
        self, _build_repo, _builder_store, monkeypatch, changed,
    ):
        from gita.index import builder
        from gita.vcs.git import CommittedRepo

        fixture = _build_repo({b"auth.py": self._TOKEN}, {b"auth.py": self._TOKEN + b"\n"})
        original = self._build(fixture, _builder_store, ref=fixture["commits"][0].digest.hex())
        before = self._database_rows(_builder_store)
        request = {"since": fixture["commits"][1].digest.hex()} if changed == "boundary" else {}

        def forbidden(*args, **kwargs):
            pytest.fail("local interpretation incompatibility must be rejected before walking Git history")

        with monkeypatch.context() as guard:
            if changed != "boundary":
                previous = getattr(original.context, changed)
                fingerprint = bytes((previous[0] ^ 1,)) + previous[1:]
                module = builder.evidence if changed == "parse_fingerprint" else builder.matching
                guard.setattr(module, changed, lambda *args, **kwargs: fingerprint)
            for name in ("commit", "object_info", "iter_tree", "read_object", "changes", "shallow_boundaries"):
                guard.setattr(CommittedRepo, name, forbidden)
            guard.setattr(builder.EvidenceWorker, "__init__", forbidden)
            with pytest.raises(builder.BuildError) as refused:
                self._build(fixture, _builder_store, **request)
        assert refused.value.code == "rebuild_required"
        assert _builder_store.published_generation("default") == original.generation
        assert self._database_rows(_builder_store) == before

