    @pytest.mark.parametrize("history", ("shorter", "rebased", "second-parent-only"))
    def test_noncontinuations_refuse_without_importing_history(
        self, _forked_repo, _builder_store, monkeypatch, history,
    ):
        from gita.index import builder

        fixture = _forked_repo
        anchor, published = fixture["commits"]
        original = self._build(fixture, _builder_store)
        if history == "shorter":
            tip = anchor
        elif history == "rebased":
            tip = fixture["other"]
        else:
            tip = self._oid(self._git(
                fixture["root"], "commit-tree", fixture["tree"],
                "-p", fixture["other"].digest.hex(), "-p", published.digest.hex(), "-m", "old tip is second parent",
            ))
        before = self._database_rows(_builder_store)

        def forbidden(*args, **kwargs):
            pytest.fail("a noncontinuation must not advance semantic history")

        with monkeypatch.context() as guard:
            guard.setattr(builder._Builder, "advance", forbidden)
            guard.setattr(builder.EvidenceWorker, "__init__", forbidden)
            with pytest.raises(builder.BuildError) as refused:
                self._build(fixture, _builder_store, ref=tip.digest.hex())
        assert refused.value.code == "rebuild_required"
        assert _builder_store.published_generation("default") == original.generation
        assert _builder_store.members(original.generation) == (anchor, published)
        assert self._database_rows(_builder_store) == before

