    @pytest.mark.parametrize("failure", ("worker-timeout", "cancel-before-publish"))
    def test_incremental_failure_rolls_back_all_new_rows_and_pointer(
        self, _build_repo, _builder_store, monkeypatch, failure,
    ):
        from gita.index import builder
        from gita.index.store import IndexStore
        from gita.index.worker import EvidenceWorkerError

        fixture = _build_repo({b"base.py": self._TOKEN}, {
            b"base.py": self._TOKEN, b"a-good.py": self._OTHER,
            b"z-fail.py": self._TOKEN.replace(b"validate_token", b"last_token"),
        })
        original = self._build(fixture, _builder_store, ref=fixture["commits"][0].digest.hex())
        before = self._database_rows(_builder_store)
        successful = []
        original_parse = builder.EvidenceWorker.parse
        primary = KeyboardInterrupt("cancel incremental publication")
        persisted = []
        original_put_parse = _builder_store.put_parse

        def put_parse(result, versions):
            identifier = original_put_parse(result, versions)
            persisted.append(result.path)
            return identifier

        def parse(worker, source, path, *args, **kwargs):
            assert _builder_store.connection.in_transaction
            assert source != self._TOKEN, "the published prefix must not be reparsed"
            if failure == "worker-timeout" and path == b"z-fail.py":
                raise EvidenceWorkerError("resource_limit", "injected suffix worker timeout")
            bundle = original_parse(worker, source, path, *args, **kwargs)
            successful.append(path)
            return bundle

        def cancel(store, generation, **kwargs):
            assert store is _builder_store
            assert persisted == [b"a-good.py", b"z-fail.py"]
            assert store.generation(generation)["predecessor"] == original.generation
            assert store.published_generation("default") == original.generation
            assert store.connection.execute("SELECT count(*) FROM parse_result").fetchone()[0] > len(before["parse_result"])
            raise primary

        with monkeypatch.context() as guard:
            guard.setattr(builder.EvidenceWorker, "parse", parse)
            guard.setattr(_builder_store, "put_parse", put_parse)
            if failure == "cancel-before-publish":
                guard.setattr(IndexStore, "publish_generation", cancel)
                with pytest.raises(KeyboardInterrupt) as interrupted:
                    self._build(fixture, _builder_store)
                assert interrupted.value is primary
            else:
                with pytest.raises((builder.BuildError, EvidenceWorkerError)) as timed_out:
                    self._build(fixture, _builder_store)
                assert timed_out.value.code == "resource_limit"
                assert persisted == [b"a-good.py"]
        assert successful
        assert not _builder_store.connection.in_transaction
        assert _builder_store.published_generation("default") == original.generation
        assert self._database_rows(_builder_store) == before

    def test_open_reader_snapshot_and_old_generation_pages_survive_publication(self, tmp_path, refactor_repo):
        from gita.index.model import GitOid
        from gita.index.store import IndexStore

        fixture = {"root": refactor_repo["repo"].root}
        commits = tuple(GitOid.from_hex("sha1", value) for value in refactor_repo["commits"])
        database = tmp_path / "reader-snapshot.sqlite"
        with IndexStore.create(database) as writer:
            original = self._build(fixture, writer, ref=commits[2].digest.hex())
            old_generation = self._generation_rows(writer, original)
            with IndexStore.open(database) as reader:
                with reader.snapshot():
                    assert reader.published_generation("default") == original.generation
                    before = self._database_rows(reader)
                    first_page = reader.members(original.generation, offset=0, limit=1)
                    extended = self._build(fixture, writer)
                    assert reader.published_generation("default") == original.generation
                    assert self._database_rows(reader) == before
                    assert first_page + reader.members(original.generation, offset=1, limit=2) == commits[:3]
                    with IndexStore.open(database) as fresh:
                        assert fresh.published_generation("default") == extended.generation
                        assert fresh.members(extended.generation) == commits
                        assert self._generation_rows(fresh, original) == old_generation
                assert reader.published_generation("default") == extended.generation
                assert reader.members(original.generation, offset=2, limit=1) == commits[2:3]
                assert reader.members(original.generation, offset=3, limit=1) == ()
                assert self._generation_rows(reader, original) == old_generation

    def test_partial_frontier_recovery_preserves_unknown_departure_and_observed_identity(
        self, _build_repo, tmp_path,
    ):
        from gita.index.store import IndexStore

        common = {b"stable.py": self._OTHER, b"opaque.txt": b"unsupported evidence\n"}
        fixture = _build_repo(
            {**common, b"auth.py": self._TOKEN},
            {**common, b"auth.py": b"def incomplete(:\n"},
            {**common, b"auth.py": self._TOKEN},
        )
        database = tmp_path / "partial-frontier.sqlite"
        with IndexStore.create(database) as store:
            original = self._build(fixture, store, ref=fixture["commits"][1].digest.hex())
            seed = self._one(store, original, 0, path=b"auth.py", synthetic=False)
            stable = self._one(store, original, 1, path=b"stable.py", synthetic=False)
            departure = dict(self._departure(store, original, seed["eid"]))
            departure.pop("generation_id")
            frozen = self._generation_rows(store, original)
            assert original.status == "partial"
            assert self._bindings(store, original, 1, path=b"auth.py") == []
            assert self._departure(store, original, seed["eid"])["status"] == "unknown"
        with IndexStore.open(database, read_only=False) as store:
            extended = self._build(fixture, store)
            assert extended.context == original.context and extended.status == "partial"
            recovered = self._one(store, extended, 2, path=b"auth.py", synthetic=False)
            assert recovered["eid"] != seed["eid"] and recovered["eid"].startswith("oeid1_")
            assert recovered["definition"].id == seed["definition"].id
            assert self._one(store, extended, 2, path=b"stable.py", synthetic=False)["eid"] == stable["eid"]
            restored_departure = self._departure(store, extended, seed["eid"])
            assert {name: restored_departure[name] for name in departure} == departure
            assert self._events(store, extended, seed["eid"])[-1].flags == ("lineage_gap",)
            observed = self._events(store, extended, recovered["eid"])
            assert len(observed) == 1 and observed[0].flags == ("observed",)
            assert observed[0].source is None and observed[0].commit == fixture["commits"][2]
            assert "parse_error" in {row["reason"] for row in self._coverage(store, extended, sequence=1, path=b"auth.py")}
            states = {row["path"]: row for row in store.file_states(extended.generation, 2)}
            assert states[b"auth.py"]["status"] == "present"
            assert states[b"opaque.txt"]["status"] == "unknown" and states[b"opaque.txt"]["binding_set"] is None
            assert self._generation_rows(store, original) == frozen
            assert store.check_integrity() == ()

    def test_leaf_line_shift_uses_current_source_without_inventing_an_event(self, _build_repo, _builder_store):
        from gita.vcs.git import CommittedRepo

        prefix = b"# shifted source\n\n"
        shifted = prefix + self._TOKEN
        changed = shifted.replace(b"== 3", b">= 3")
        fixture = _build_repo(
            {b"auth.py": self._TOKEN, b"other.py": self._OTHER},
            {b"auth.py": shifted, b"other.py": self._OTHER},
            {b"auth.py": shifted, b"other.py": self._OTHER.replace(b"* 7", b"* 11")},
            {b"auth.py": changed, b"other.py": self._OTHER.replace(b"* 7", b"* 11")},
        )
        original = self._build(fixture, _builder_store, ref=fixture["commits"][0].digest.hex())
        extended = self._build(fixture, _builder_store)
        assert extended.context == original.context and extended.commits == 4
        leaves = [self._one(_builder_store, extended, sequence, path=b"auth.py", synthetic=False)
                  for sequence in range(4)]
        assert len({leaf["eid"] for leaf in leaves}) == 1
        assert leaves[0]["definition"].id != leaves[1]["definition"].id == leaves[2]["definition"].id
        assert leaves[0]["version"] == leaves[1]["version"] == leaves[2]["version"]
        parse_ids = [next(row["parse_id"] for row in _builder_store.file_states(extended.generation, sequence)
                          if row["path"] == b"auth.py") for sequence in range(4)]
        assert parse_ids[0] != parse_ids[1] == parse_ids[2] != parse_ids[3]
        events = self._events(_builder_store, extended, leaves[0]["eid"])
        assert len(events) == 2
        assert events[-1].commit == fixture["commits"][3] and events[-1].parent == fixture["commits"][2]
        assert events[-1].source == leaves[2]["occurrence"].id
        assert events[-1].destination == leaves[3]["occurrence"].id
        assert events[-1].flags == ("body_changed",) and events[-1].material is True
        with CommittedRepo(fixture["root"]) as repository:
            for sequence in (1, 2):
                occurrence, span = leaves[sequence]["occurrence"], leaves[sequence]["definition"].span
                assert occurrence.commit == fixture["commits"][sequence]
                assert span.start_byte == len(prefix) and span.start_line == 3
                assert repository.source(occurrence.commit, occurrence.path, occurrence.blob, occurrence.mode,
                                         span.start_byte, span.end_byte) == self._TOKEN[:-1]
